def is_palindrome(s):
    t = ''.join(c.lower() for c in s if c.isalnum())
    return t == t[::-1]

def mask_card(number):
    digits = number.replace(" ", "")
    return "*" * (len(digits) - 4) + digits[-4:]

def are_anagrams(a, b):
    clean = lambda s: sorted(s.replace(' ', '').lower())
    return clean(a) == clean(b)
